// intake.dispute.raise / .decide — E2 AC5, SOP-DEL-01 §9. Generated by `pnpm gen:command`; acceptance cases added.
// The card goes through the real intake commands: submitted, returned, disputed, decided.
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, countRows, createFakeClock, createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  Conflict,
  Forbidden,
  grantOf,
  NotFound,
  openTestKernel,
  RuleViolation,
  type TestKernel,
} from '../../kernel/index.ts';
import { createClient, createSite } from '../../org/index.ts';
import { authoriseConditionalStart } from '../commands/authorise-conditional-start.ts';
import { decideDispute } from '../commands/decide-dispute.ts';
import { decideIntake } from '../commands/decide-intake.ts';
import { raiseDispute } from '../commands/raise-dispute.ts';
import { saveHandoverCard } from '../commands/save-handover-card.ts';
import { submitHandoverCard } from '../commands/submit-handover-card.ts';
import { itemCodes } from '../rules/handover-checklist.ts';

const sales = aStaffActor({ roles: ['sales'] });
const director = aStaffActor({ roles: ['director'] });
const sponsor = aStaffActor({ roles: ['sponsor'] });
const clock = createFakeClock(new Date('2026-11-20T09:00:00Z')); // Friday: +2 working days (GB) = Tue 24 Nov
let testDb: TestDatabase;
let t: TestKernel;
let siteA: string;
const raise = (actor = sales) =>
  t.kernel.execute(raiseDispute, actor, { siteId: siteA, reason: 'C3 was in the folder' }, 'test');
const decide = (outcome: string, actor = sponsor) =>
  t.kernel.execute(decideDispute, actor, { siteId: siteA, outcome, note: 'Checked the folder' }, 'test');

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url, { clock: clock.now });
  t.grant(director, createClient.permission, createSite.permission, decideIntake.permission);
  t.grant(sales, saveHandoverCard.permission, submitHandoverCard.permission, raiseDispute.permission);
  t.grant(sponsor, decideDispute.permission, authoriseConditionalStart.permission);
  const a = await t.kernel.execute(
    createClient,
    director,
    { shortCode: 'CLIENTA', name: 'Client A' },
    'test',
  );
  const place = { countryCode: 'GB', cityCode: 'LON', cityName: 'London', name: 'Mall A', standard: 'L' };
  ({ id: siteA } = await t.kernel.execute(createSite, director, { clientId: a.id, ...place }, 'test'));
  const items = itemCodes.map((code) =>
    code.startsWith('F') ? { code, status: 'provided' } : { code, status: 'provided', value: 'in folder' },
  );
  const card = {
    siteId: siteA,
    content: { identification: { projectName: 'Counting', projectType: 'new' } },
    items,
    installsOrConfigures: true,
    newClientOrPlace: true,
  };
  await t.kernel.execute(saveHandoverCard, sales, card, 'test');
  await t.kernel.execute(submitHandoverCard, sales, { siteId: siteA }, 'test');
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('intake disputes (SOP-DEL-01 §9)', () => {
  it('Sales raises, the sponsor decides; nobody else', () => {
    expect([grantOf(raiseDispute.permission)?.roles, grantOf(decideDispute.permission)?.roles]).toEqual([
      ['sales'],
      ['sponsor'],
    ]);
  });

  it('only a Returned decision can be disputed', async () => {
    await expect(raise()).rejects.toBeInstanceOf(RuleViolation);
    await t.kernel.execute(
      decideIntake,
      director,
      { siteId: siteA, decision: 'returned', folderStandard: 'L', reasons: 'C3 unusable', conditions: [] },
      'test',
    );
  });

  it('raised: the sponsor has 2 working days; once per return', async () => {
    expect((await raise()).dueOn).toBe('2026-11-24');
    await expect(raise()).rejects.toBeInstanceOf(Conflict);
  });

  it('work does not start while the dispute is open: Conditional Start refused, even on a new draft', async () => {
    const items = itemCodes.map((code) => ({ code, status: 'provided' }));
    const draft = {
      siteId: siteA,
      content: { identification: { projectName: 'Counting', projectType: 'new' } },
      items,
      installsOrConfigures: true,
      newClientOrPlace: true,
    };
    await t.kernel.execute(saveHandoverCard, sales, draft, 'test');
    await expect(
      t.kernel.execute(
        authoriseConditionalStart,
        sponsor,
        { siteId: siteA, missingItems: ['C3'], deadline: '2026-11-24', writtenRef: 'DingTalk 1' },
        'test',
      ),
    ).rejects.toThrow(/SOP-DEL-01 §9/);
  });

  it('only the sponsor decides, once; the decision is recorded', async () => {
    await expect(decide('upheld', director)).rejects.toBeInstanceOf(Forbidden);
    expect(await decide('overturned')).toMatchObject({ outcome: 'overturned' });
    await expect(decide('upheld')).rejects.toBeInstanceOf(Conflict);
    expect(
      await countRows(testDb.url, `intake_dispute WHERE outcome = 'overturned' AND decided_by = $1`, [
        sponsor.id,
      ]),
    ).toBe(1);
  });

  it('nothing to decide on a project without a dispute', async () => {
    await expect(
      t.kernel.execute(decideDispute, sponsor, { siteId: director.id, outcome: 'upheld' }, 'test'),
    ).rejects.toBeInstanceOf(NotFound);
  });
});
